function HostDashboard() {
    return <><div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">RENTAL BUSINESS</p><h1 className="mt-1 text-2xl font-black tracking-tight text-slate-950">Your rental fleet at a glance.</h1><p className="mt-1 text-sm text-slate-500">Manage vehicle availability, reservations and return inspections.</p></div><Link href="/host/vehicles?add=1" className="btn-primary"><Plus size={16}/> Add vehicle</Link></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Total vehicles" value="08" icon={<CarFront size={20}/>} tone="blue"/><MetricCard label="Active reservations" value="03" change="16.2%" icon={<CalendarCheck size={20}/>} tone="teal"/><MetricCard label="Monthly earnings" value="PKR 124,000" change="11.6%" icon={<Wallet size={20}/>} tone="purple"/><MetricCard label="Host rating" value="4.6 / 5" icon={<Star size={20}/>} tone="amber" footnote="From 39 reviews"/></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><div className="surface p-5"><SectionHeading title="Recent reservations" subtitle="Upcoming handovers and returns" action={<Link href="/host/reservations" className="text-xs font-bold text-teal-700">View all <ArrowRight size={12} className="inline"/></Link>}/><div className="space-y-3">{[{ name: "Toyota Corolla GLi", customer: "Hamza Raza", date: "Today · 3:00 PM – 11 Oct", price: "PKR 8,500", status: "Pickup due", tone: "amber", image: cars[0].image }, { name: "Honda Civic Oriel", customer: "Ayesha Khan", date: "Tomorrow · 9:00 AM – 14 Oct", price: "PKR 36,000", status: "Confirmed", tone: "green", image: cars[1].image }, { name: "Suzuki Alto VXL", customer: "Usman Ahmed", date: "15 Oct · 10:00 AM – 16 Oct", price: "PKR 4,500", status: "Confirmed", tone: "green", image: cars[2].image }].map((item) => <div key={item.name + item.customer} className="flex flex-wrap items-center gap-3 rounded-xl border border-slate-100 p-3"><img src={item.image} alt={item.name} className="h-14 w-20 rounded-lg object-cover"/><div className="min-w-0 flex-1"><p className="text-xs font-extrabold text-slate-800">{item.name}</p><p className="mt-1 text-[10px] text-slate-500">{item.customer} · {item.date}</p><div className="mt-2"><StatusBadge tone={item.tone}>{item.status}</StatusBadge></div></div><div className="text-right"><p className="text-xs font-extrabold text-slate-900">{item.price}</p><p className="mt-1 text-[9px] text-slate-400">booking total</p></div></div>)}</div></div><div className="space-y-5"><div className="surface p-5"><SectionHeading title="Vehicle availability" subtitle="Current fleet status"/><div className="flex items-center gap-4"><div className="relative grid h-28 w-28 place-items-center"><svg viewBox="0 0 100 100" className="h-28 w-28 -rotate-90"><circle cx="50" cy="50" r="38" fill="none" stroke="#e2e8f0" strokeWidth="12"/><circle cx="50" cy="50" r="38" fill="none" stroke="#0d9488" strokeWidth="12" strokeDasharray="159 239" strokeLinecap="round"/></svg><div className="absolute text-center"><p className="text-xl font-black text-slate-900">67%</p><p className="text-[9px] text-slate-400">booked</p></div></div><div className="flex-1 space-y-3">{[{ label: "On rental", count: "5", color: "bg-teal-500" }, { label: "Available", count: "2", color: "bg-slate-300" }, { label: "Maintenance", count: "1", color: "bg-amber-400" }].map((item) => <div key={item.label} className="flex items-center justify-between gap-3"><span className="flex items-center gap-2 text-[10px] text-slate-600"><span className={`h-2 w-2 rounded-full ${item.color}`}/>{item.label}</span><span className="text-xs font-bold text-slate-900">{item.count}</span></div>)}</div></div><Link href="/host/calendar" className="btn-outline mt-4 w-full"><CalendarDays size={14}/> Open availability calendar</Link></div><div className="surface p-5"><SectionHeading title="Action checklist"/><div className="space-y-3">{[{ title: "Complete return inspection", meta: "Honda City · booking RN-2012", tone: "amber" }, { title: "Update insurance document", meta: "Suzuki Alto · expires 25 Oct", tone: "red" }, { title: "New reservation request", meta: "Toyota Corolla · 2 days", tone: "blue" }].map((item) => <div key={item.title} className="flex items-start gap-2.5"><span className={`mt-0.5 h-2 w-2 rounded-full ${item.tone === "amber" ? "bg-amber-500" : item.tone === "red" ? "bg-rose-500" : "bg-blue-500"}`}/><div><p className="text-[11px] font-bold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{item.meta}</p></div></div>)}</div></div></div></div></>;
}
